const CACHE_NAME = 'drone-companion-cache-v1';
const urlsToCache = [
  '/',
  '/index.html',
  // Add paths to CSS and JS bundles generated by Vite/Vue build process later
  // '/assets/index.css', // Example placeholder - will be hashed
  // '/assets/index.js', // Example placeholder - will be hashed
  '/manifest.json',
  '/icons/icon-192x192.png', // Cache placeholder icons
  '/icons/icon-512x512.png'
];

// Install event: Cache core assets
self.addEventListener('install', event => {
  console.log('[Service Worker] Install');
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => {
        console.log('[Service Worker] Caching app shell');
        // Use addAll for atomic caching
        return cache.addAll(urlsToCache.map(url => new Request(url, { cache: 'reload' })));
      })
      .then(() => {
        console.log('[Service Worker] App shell cached successfully');
        // Activate the new service worker immediately
        return self.skipWaiting();
      })
      .catch(error => {
        console.error('[Service Worker] Caching failed:', error);
      })
  );
});

// Activate event: Clean up old caches
self.addEventListener('activate', event => {
  console.log('[Service Worker] Activate');
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (cacheName !== CACHE_NAME) {
            console.log('[Service Worker] Deleting old cache:', cacheName);
            return caches.delete(cacheName);
          }
        })
      );
    })
    .then(() => {
        console.log('[Service Worker] Activated successfully');
        // Take control of clients immediately
        return self.clients.claim();
    })
  );
});

// Fetch event: Serve cached assets or fetch from network
self.addEventListener('fetch', event => {
  console.log('[Service Worker] Fetching:', event.request.url);
  // Exclude API calls or specific paths if needed later

  // Basic cache-first strategy for app shell assets
  event.respondWith(
    caches.match(event.request)
      .then(response => {
        if (response) {
          console.log('[Service Worker] Returning from cache:', event.request.url);
          return response; // Return the cached version
        }
        console.log('[Service Worker] Fetching from network:', event.request.url);
        return fetch(event.request); // Fetch from network if not in cache
      })
      .catch(error => {
        console.error('[Service Worker] Fetch failed:', error);
        // Optionally return a fallback offline page here
      })
  );
}); 